/* === 春天的开场白 Spring's Prologue 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. === */

/* --- 1. 字体导入 (全新日系/中文自定义字体) --- */
@import url('https://fonts.googleapis.com/css2?family=Yomogi&display=swap'); /* 谷歌日文/英文可爱手写体 */
@import url("https://fontsapi.zeoseven.com/200/main/result.css"); /* 全局中文: cjkFonts 全瀨體 */
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  /* 代码: nzgrRuYinZouZhangKai */
@import url("https://fontsapi.zeoseven.com/120/main/result.css"); /* 引用: CEF Fonts CJK Mono */
@import url("https://fontsapi.zeoseven.com/7/main/result.css");   /* 标题: Zhuque Fangsong */

/* --- 2. 核心颜色与变量设定 --- */
:root {
    --theme-bg-color: #FFF0F5; /* 浅樱花粉底色 */
    --theme-bg-mid: #FFB6C1; /* 樱花主粉色 */
    --card-bg: #FFFDFE; /* 纯洁的信纸白 */
    --accent-pink: #FF85A2; /* 活力元气粉 */
    --accent-blue: #A2C8F3; /* 制服水手蓝 (点缀) */
    --text-main: #5D4037; /* 栗色字体，比纯黑更温和 */
    --text-subtle: #9E7A7A; /* 灰茶色 */

    --font-english: 'Yomogi', cursive;
    --font-main: "cjkFonts 全瀨體", var(--font-english), sans-serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-quote: "CEF Fonts CJK Mono", var(--font-english), monospace;
    --font-title: "Zhuque Fangsong (technical preview)", var(--font-english), serif;
}

/* --- 3. 全局样式与无阴影无边框设定 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: url('https://images.unsplash.com/photo-1522383225653-ed111181a951?q=80&w=2076&auto=format&fit=crop'); /* 柔美的樱花开场白底图 */
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
/* 浪漫的光斑滤镜层 */
body::after {
    content: ''; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
    background: radial-gradient(circle at bottom left, rgba(255,182,193,0.15), transparent 60%);
    pointer-events: none; z-index: 9999; mix-blend-mode: multiply;
}

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title) !important; color: var(--accent-pink); font-weight: normal; }

/* 针对代码块与引用的专属字体应用 */
pre code, .mes_text code { font-family: var(--font-code) !important; background-color: rgba(255, 240, 245, 0.6) !important; color: var(--accent-pink); padding: 2px 6px; border-radius: 4px; }
blockquote, .mes_text blockquote { font-family: var(--font-quote) !important; border-left: 4px solid var(--accent-blue) !important; background-color: rgba(162, 200, 243, 0.1) !important; padding: 10px 15px; margin: 10px 0; border-radius: 0 8px 8px 0; color: #4A6572; }

/* --- 4. 顶部导航栏 & 抽屉背景 --- */
#top-settings-holder { position:relative; background-color: rgba(255, 253, 254, 0.7); backdrop-filter: blur(12px); border: none !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); }
.drawer-icon.fa-fw:hover { transform: scale(1.15) rotate(8deg); }

/* 导航栏贴图替换 */
.drawer-icon.fa-sliders, #ai-config-button .drawer-icon, .drawer-icon.fa-font, #advanced-formatting-button .drawer-icon, .drawer-icon.fa-user, #user-settings-button .drawer-icon, .drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon, .drawer-icon.fa-face-smile, #persona-management-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/mcKm/1425X1953/2026-05-01_134228.png/webp'); 
}
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon, .drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon, .drawer-icon.fa-image, .drawer-icon.fa-panorama, .drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon, .drawer-icon.fa-address-card, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/3oxW/973X967/2026-04-25_183406.png/webp'); 
}

/* 抽屉与弹窗背景图替换 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(255, 253, 254, 0.85), rgba(255, 253, 254, 0.95)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/Iihx/1200X800/bcf6df318ffda4898af546fcad2e5fe9.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 16px !important; color: var(--text-main) !important;
}

/* ------------------------------------------------- */
/* [5] 底部悬浮输入栏 (日系学院风·无内凹·无阴影) */
/* ------------------------------------------------- */
#form_sheld { position: absolute !important; bottom: 15px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }

#send_form, body.no-blur #send_form { 
    pointer-events: auto;
    width: 90% !important; 
    max-width: 800px !important; 
    margin: 0 auto !important;
    border-radius: 25px !important; 
    background-color: rgba(255, 253, 254, 0.85) !important; 
    padding: 10px 15px !important; 
    backdrop-filter: blur(12px) !important; 
    -webkit-backdrop-filter: blur(12px) !important; 
    border: none !important; 
    box-shadow: none !important; /* 强制贯彻全局无阴影 */
    transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) !important; 
}

/* 交互悬浮：上浮效果并加深白粉色底色，依旧保持无阴影 */
#send_form:hover, body.no-blur #send_form:hover { 
    transform: translateY(-5px) !important; 
    background-color: rgba(255, 253, 254, 0.98) !important; 
    box-shadow: none !important; 
    border: none !important; 
}

#rightSendForm, #leftSendForm { gap: 10px; }

#send_textarea { 
    clip-path: none !important; 
    border: none !important; 
    background: transparent !important; 
    color: var(--text-main) !important; 
    font-size: 16px !important; 
    box-shadow: none !important; 
}

#nonQRFormItems { position: relative; }

/* 隐藏原生提示词 */
#send_textarea::placeholder, #send_textarea::-webkit-input-placeholder { 
    color: transparent !important; text-shadow: none !important; opacity: 0 !important; 
}

/* 日文伪提示 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: "📝 放課後の伝言を書いている... "; 
    color: var(--accent-pink); 
    position: absolute; 
    top: 50%; 
    transform: translateY(-50%); 
    left: 50px; 
    right: 70px; 
    text-align: center; 
    font-family: var(--font-english); 
    font-size: 0.6em; 
    pointer-events: none; 
    white-space: nowrap; 
    overflow: hidden; 
    text-overflow: ellipsis;
    opacity: 0.8;
    animation: heartbeat 2.5s infinite alternate; /* 保留可爱的呼吸特效 */
}

/* 隐藏原生按钮图标文字 */
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before, #mes_impersonate::before { display: none !important; }

/* 按钮尺寸与基础动效 */
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button, #mes_impersonate { 
    width: 32px; 
    height: 32px; 
    background-size: contain; 
    background-repeat: no-repeat; 
    background-position: center; 
    transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275); 
    font-size: 0; 
    border: none; 
    background-color: transparent; 
}

/* 按钮悬浮放大+俏皮旋转 */
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover, #mes_impersonate:hover { 
    transform: scale(1.15) rotate(10deg); 
}

/* 主题贴图替换 */
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/9aqg/1641X1760/2026-05-01_134120.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/fqyV/1571X1235/2026-05-01_134214.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/qrOT/1663X1525/2026-05-01_134147.png/webp'); }

/* 辅助功能键采用滤镜复用贴图以适应不同功能 */
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/9aqg/1641X1760/2026-05-01_134120.png/webp'); filter: hue-rotate(320deg) brightness(1.2); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/fqyV/1571X1235/2026-05-01_134214.png/webp'); filter: hue-rotate(45deg); }
#mes_impersonate { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/9aqg/1641X1760/2026-05-01_134120.png/webp'); filter: saturate(0.5); }

/* --- 6. 核心：学院风消息框 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 85px auto 55px !important; 
    width: 90%; max-width: 820px; 
    background-color: var(--card-bg) !important;
    border-radius: 12px !important; 
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
    overflow: visible !important;
    position: relative; z-index: 10;
    transition: transform 0.3s ease;
}
.mes:hover { transform: translateY(-2px); }

/* 消息框顶部动态GIF海报横幅区 */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; height: 160px !important; min-height: 160px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-top-left-radius: 12px; border-top-right-radius: 12px;
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/AAAi/540X303/%E2%86%92%CB%9A%E2%82%8A%C2%B7gif_aes_anime_%E0%A9%AD_.gif/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/sWTN/500X278/%E4%B8%8B%E8%BD%BD.gif/webp'); }

/* 头像调整 - 与横幅自然融合 */
.mes .avatar {
    position: absolute;
    top: -35px; 
    width: 80px; height: 80px; 
    background: #FFFDFE !important; 
    padding: 5px !important; 
    z-index: 30; display: flex !important; align-items: center; justify-content: center;
    border-radius: 50% !important; 
}
.mes[is_user="false"] .avatar { left: 30px; }
.mes[is_user="true"] .avatar { right: 30px; left: auto; }
.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; border-radius: 50% !important; 
}

/* 装饰性文字伪元素：青春の一ページ */
.mes::before {
    content: '「青春の1ページ」';
    position: absolute; bottom: 15px; right: -50px;
    font-family: var(--font-english); font-size: 18px;
    color: rgba(255, 133, 162, 0.4);
    writing-mode: vertical-rl;
    letter-spacing: 4px;
    pointer-events: none; z-index: 0;
    transform: rotate(5deg);
}
.mes[is_user="true"]::before { right: auto; left: -50px; transform: rotate(-5deg); }

/* 消息主体区 */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 25px 35px 35px 35px !important; position: relative; border: none !important; overflow: visible !important; min-height: 100px !important; z-index: 10; }
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; position: relative; z-index: 2; }

/* --- 名字设计：气泡对话框 --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }

.mes .mes_block > .ch_name { 
    display: inline-flex !important; position: absolute; 
    top: -180px !important; /* 彻底移动到消息框上方 */
    align-items: center !important; 
    background: #FFFDFE !important; 
    z-index: 100; 
    padding: 6px 18px !important; 
    border-radius: 20px !important;
    width: auto !important;
    min-width: 80px;
    justify-content: center;
}

/* 气泡小尾巴 (伪类绘制三角形，只用border-style) */
.mes .mes_block > .ch_name::after {
    content: ''; position: absolute;
    bottom: -8px; 
    border-width: 10px 10px 0;
    border-style: solid !important;
    border-color: #FFFDFE transparent transparent transparent !important;
}

.mes[is_user="false"] .ch_name { left: 35px; }
.mes[is_user="false"] .ch_name::after { left: 20px; }
.mes[is_user="true"] .ch_name { right: 35px; }
.mes[is_user="true"] .ch_name::after { right: 20px; }

.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 8px !important; }
.mes .ch_name .name_text { font-family: var(--font-english); font-size: 20px !important; color: var(--accent-pink) !important; font-weight: bold; letter-spacing: 1px; }

/* --- 思维链 (日系手帐风) --- */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "🌸 桜の花びらが舞うように思考を巡らせる... (Thinking)"; 
    font-family: var(--font-english); font-size: 16px !important; 
    color: var(--accent-pink); visibility: visible; letter-spacing: 1px; 
}
.mes_reasoning { padding-left: 18px !important; margin-bottom: 25px !important; color: var(--text-subtle); font-family: var(--font-code); font-size: 0.95em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 4px; 
    background: repeating-linear-gradient(45deg, var(--accent-pink), var(--accent-pink) 6px, transparent 6px, transparent 12px);
    border-radius: 4px;
}
.mes .mes_text { line-height: 2.1; color: var(--text-main); font-size: 16px; text-align: justify; }

/* --- 楼层信息与时间戳 --- */
.mes .mesIDDisplay, .mes .mes_timer { position: static !important; color: var(--accent-blue) !important; font-size: 14px !important; font-family: var(--font-english); }
.mesIDDisplay::before { content: '📓 交換日記 第 '; }
.mesIDDisplay::after { content: ' ページ'; }

/* 按钮区 */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0.1; transition: opacity 0.3s ease; pointer-events: auto !important; margin-top: 15px; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(255, 240, 245, 0.9) !important; color: var(--accent-pink) !important; padding: 7px !important; border-radius: 50% !important; cursor: pointer; transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275); font-size: 14px !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-pink) !important; color: #fff !important; transform: scale(1.15) rotate(15deg); }

/* 正在输入动画 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260501/qrOT/1663X1525/2026-05-01_134147.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: float-sakura 1.5s infinite ease-in-out; border: none !important; height: 50px !important; width: 50px !important; margin: 15px auto !important; }
#typing_indicator .dot { display: none !important; }

/* --- 全局UI设定与输入框 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: rgba(255, 253, 254, 0.6) !important; border-radius: 12px !important; padding: 10px 15px !important; margin-bottom: 8px !important; color: var(--accent-pink) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(255, 240, 245, 0.6) !important; color: var(--text-main) !important; border-radius: 8px !important; padding: 10px !important; }
input:focus, textarea:focus, select:focus { outline: none !important; background-color: rgba(255, 253, 254, 1) !important; }
.menu_button { background-color: rgba(255, 253, 254, 0.6) !important; color: var(--text-subtle) !important; transition: all 0.3s ease; border-radius: 10px !important; }
.menu_button:hover { background-color: var(--accent-pink) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-blue) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(255, 253, 254, 0.9); z-index: 0; border-radius: 16px; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-pink) !important; color: #fff !important; }

/* 手机端适配调整 */
@media (max-width: 768px) {
    .mes { margin: 80px auto 45px !important; }
    .mes::before { display: none; } /* 手机端隐藏侧边日语以免遮挡 */
    .mes .avatar { width: 65px; height: 65px; top: -30px; }
    .mes .ch_name .name_text { font-size: 18px !important; }
    .mes .mesAvatarWrapper { height: 130px !important; min-height: 130px !important; }
    .mes .mes_block > .ch_name { top: -45px !important; padding: 4px 14px !important; }
    #send_form { width: 95% !important; padding: 10px 15px !important; }
}

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: rgba(255,253,254,0.9) !important; color: var(--accent-pink) !important; border-radius: 12px !important; padding: 12px 25px !important; margin: 10px 8px !important; transition: all 0.3s ease !important; font-weight: bold; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-blue) !important; color: #fff !important; transform: translateY(-3px) !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--theme-bg-mid) !important; color: #fff !important; transform: translateY(-3px) !important; }

/* ================================================== */
/* 1. 头像布局：气泡对话框侧边半悬浮 */
/* ================================================== */
.mes .avatar {
    position: absolute !important;
    top: 15px !important; /* 与气泡顶部对齐偏下一点，更贴合对话感 */
    width: 55px !important; 
    height: 55px !important; 
    background: #FFFDFE !important; 
    padding: 4px !important; 
    z-index: 30 !important; 
    display: flex !important; 
    align-items: center !important; 
    justify-content: center !important;
    border-radius: 50% !important; 
    box-shadow: none !important;
}

/* AI 头像半挂在气泡左外侧 */
.mes[is_user="false"] .avatar { left: -25px !important; }
/* 用户头像半挂在气泡右外侧 */
.mes[is_user="true"] .avatar { right: -25px !important; left: auto !important; }

.mes .avatar img { 
    width: 100% !important; 
    height: 100% !important; 
    object-fit: cover !important; 
    border-radius: 50% !important; 
}


/* ================================================== */
/* 2. 楼层信息与时间戳：彻底提取，悬浮在气泡外侧底部 */
/* ================================================== */
.mes .mesIDDisplay, .mes .timestamp { 
    position: absolute !important; 
    bottom: -30px !important; 
    color: var(--text-subtle) !important; 
    font-size: 13px !important; 
    font-family: var(--font-english) !important; 
    background: rgba(255, 253, 254, 0.7) !important; /* 加上一层浅浅的底色 */
    padding: 4px 12px !important; 
    border-radius: 12px !important;
    backdrop-filter: blur(4px) !important;
    white-space: nowrap !important;
}

/* AI 气泡：楼层信息靠左下方，时间戳靠右下方 */
.mes[is_user="false"] .mesIDDisplay { left: 15px !important; }
.mes[is_user="false"] .mes_timer { right: 15px !important; }

/* 用户气泡：楼层信息靠右下方，时间戳靠左下方 */
.mes[is_user="true"] .mesIDDisplay { right: 15px !important; }
.mes[is_user="true"] .mes_timer { left: 15px !important; }


/* ================================================== */
/* 3. 手机端自动防遮挡适配 (时间戳内置最终修正版) */
/* ================================================== */
@media (max-width: 768px) {
    /* 头像样式保持不变 */
    .mes .avatar { width: 45px !important; height: 45px !important; top: 10px !important; }
    .mes[is_user="false"] .avatar { left: -10px !important; }
    .mes[is_user="true"] .avatar { right: -10px !important; left: auto !important; }

    /* --- 楼层信息：保持为外部悬浮标签 --- */
    .mes .mesIDDisplay {
        font-size: 11px !important;
        padding: 3px 10px !important;
        bottom: -25px !important; /* 调整到底部外侧 */
        z-index: 2 !important;
    }
    .mes[is_user="false"] .mesIDDisplay { left: 15px !important; right: auto !important; }
    .mes[is_user="true"] .mesIDDisplay { right: 15px !important; left: auto !important; }


    /* --- 时间戳：精确内置于 .mes_block 右下角 --- */
    .mes .timestamp {
        position: absolute !important;
        bottom: 10px !important; 
        right: 20px !important;  
        top: auto !important;
        left: auto !important;
        background: transparent !important; /* 去掉小药丸背景 */
        backdrop-filter: none !important;
        padding: 0 !important; /* 去掉内外边距 */
        font-size: 11px !important;
        color: var(--text-subtle) !important;
        opacity: 0.8; /* 稍微降低不透明度，使其更柔和 */
        z-index: 5 !important;
    }
}
